#!/usr/bin/env python3
"""Independent audit probes for the submitted P9-2.1 leaf; never changes production.

Usage:
  PYTHONPATH=src python P9-2.1-independent-stress-tests.py --repo . --output result.json

Exit 1 means at least one required regression expectation failed. Advisory
characterizations are reported separately. Synthetic labels are NOT admitted
model identities, solver outputs, transactions, or conformance evidence.
"""
from __future__ import annotations

import argparse
from array import array
from collections import Counter
from collections.abc import Mapping
from copy import copy, deepcopy
from dataclasses import asdict, fields, replace
import hashlib
import importlib
import itertools
import json
import math
from pathlib import Path
import platform
import random
import sys


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    root = args.repo.resolve()
    sys.path.insert(0, str(root / 'src'))
    s = importlib.import_module('pygrc.models.grc_v4_state')
    GRCEvent = importlib.import_module('pygrc.core.events').GRCEvent
    try:
        np = importlib.import_module('numpy')
    except ImportError:
        np = None
    rows = []

    def require(condition: bool, message: str = 'assertion failed') -> None:
        if not condition:
            raise AssertionError(message)

    def equal(actual, expected):
        require(actual == expected, f'actual={actual!r}; expected={expected!r}')
        return {'actual': repr(actual), 'expected': repr(expected)}

    def reject(factory):
        try:
            actual = factory()
        except (TypeError, ValueError, UnicodeError) as exc:
            return {'exception': type(exc).__name__, 'message': str(exc)}
        raise AssertionError(f'invalid input accepted: {actual!r}')

    def check(name, group, assertion, tier='required'):
        try:
            observed = assertion()
            row = {'id': name, 'group': group, 'tier': tier, 'pass': True,
                   'observed': observed}
        except Exception as exc:
            row = {'id': name, 'group': group, 'tier': tier, 'pass': False,
                   'exception': type(exc).__name__, 'message': str(exc)}
        rows.append(row)

    def authority(channel, values):
        data = {'C': [1.0, 2.0], 'W_A': None, 'Z_4': None}
        data[channel] = values
        return s.GRCV4AuthoritativeState(**data)

    def lifecycle_data(candidate='C', realization='OS'):
        hist = candidate == 'A'
        carrier = realization in ('PC', 'CI+PC')
        current = s.GRCV4AuthoritativeState(
            [1.0, 3.0], [0.75] if hist else None,
            [-0.5, 0.25] if carrier else None)
        reset_authority = s.GRCV4AuthoritativeState(
            [2.5, 1.5], [1.25] if hist else None,
            [-1.0, 0.5] if carrier else None)
        return dict(
            step_index=7, time=1.75,
            graph={'live_node_ids': ['a', 'b'], 'edges': [{'id': 'ab'}]},
            graph_digest='synthetic-graph', orientation_identity='a-to-b',
            profile={'identity_payload': {'candidate': candidate, 'realization': realization},
                     'params_resolved': {'reference': [2.0, 4.0]},
                     'complete_profile_id': 'synthetic-profile'},
            context_contract_id='synthetic-context', context_value_digest=None,
            current=current,
            reset=s.GRCV4ResetBaseline(reset_authority, 'synthetic-graph', 'a-to-b',
                  'synthetic-profile', 'synthetic-context', 4.0, 'synthetic-reset'),
            Q_target=4.0, receipt_ledger=[{'id': 'prior', 'payload': [1, {'flag': True}]}],
            scientific_state_digest='synthetic-state', lifecycle_digest='synthetic-lifecycle')

    def result_data():
        return dict(step_index=7, time=1.75,
            events=[GRCEvent('synthetic', 7, {'nested': [1, {'flag': True}]}, 'GRCV4')],
            observables={'x': [0.25]}, active_profile_id='synthetic-profile',
            active_model_identity='synthetic-model', operation_disposition='committed',
            solver_disposition='valid_root', committed=True, commit_id='synthetic-commit',
            failure=None, emitted_receipts=[{'id': 'delta', 'payload': [1]}])

    # Strict type-preserving JSON comparison is independent of production __eq__.
    def typed_json(value):
        return json.dumps(value, sort_keys=True, ensure_ascii=False, allow_nan=False,
                          separators=(',', ':'))

    def random_json(rng, depth):
        scalars = [None, True, False, 0, 1, -1, 0.0, 1.25, '', 'e\u0301', 'é', '😀']
        if depth == 0 or rng.random() < 0.4:
            return rng.choice(scalars)
        if rng.random() < 0.5:
            return [random_json(rng, depth - 1) for _ in range(rng.randrange(5))]
        return {f'k{i}': random_json(rng, depth - 1) for i in range(rng.randrange(5))}

    def disturb(value):
        if isinstance(value, dict):
            for child in tuple(value.values()):
                disturb(child)
            value['__audit_mutation__'] = [99]
        elif isinstance(value, list):
            for child in tuple(value):
                disturb(child)
            value.append({'__audit_mutation__': True})

    for seed in range(200):
        def random_ownership(seed=seed):
            rng = random.Random(seed)
            source = {'payload': random_json(rng, 5), 'seed': seed}
            expected = typed_json(deepcopy(source))
            frozen = s.FrozenJSONMap(source)
            disturb(source)
            equal(typed_json(frozen.to_dict()), expected)
            output = frozen.to_dict()
            disturb(output)
            equal(typed_json(frozen.to_dict()), expected)
            duplicate = deepcopy(frozen)
            disturb(duplicate.to_dict())
            equal(typed_json(duplicate.to_dict()), expected)
            return {'seed': seed, 'input_output_and_copy_detached': True}
        check(f'JSON-OWNERSHIP-{seed:03}', 'recursive_value_ownership', random_ownership)

    for depth in (1, 3, 8, 20, 60):
        def shared_alias(depth=depth):
            tail = [1, {'bool': False}]
            left = tail
            for _ in range(depth):
                left = {'next': left}
            source = {'left': left, 'right': tail}
            expected = typed_json(deepcopy(source))
            value = s.FrozenJSONMap(source)
            tail[1]['bool'] = True
            equal(typed_json(value.to_dict()), expected)
        check(f'SHARED-ACYCLIC-{depth}', 'recursive_value_ownership', shared_alias)

    def duplicate_key_mapping():
        class Duplicate(Mapping):
            def __iter__(self): return iter(('a',))
            def __len__(self): return 1
            def __getitem__(self, key): return 1
            def items(self): return [('a', 1), ('a', 2)]
        return reject(lambda: s.FrozenJSONMap(Duplicate()))
    check('JSON-DUPLICATE-KEY', 'local_shape', duplicate_key_mapping)
    for kind in ('dict-cycle', 'list-cycle', 'mixed-cycle'):
        def cycle(kind=kind):
            a, b = {}, []
            if kind == 'dict-cycle': a['a'] = a
            elif kind == 'list-cycle': b.append(b); a['a'] = b
            else: a['a'] = b; b.append(a)
            return reject(lambda: s.FrozenJSONMap(a))
        check(kind, 'local_shape', cycle)
    for value in [math.nan, math.inf, -math.inf, -0.0, 2**53, -(2**53), b'x', {1}, object()]:
        check('JSON-REJECT-' + repr(value), 'local_shape',
              lambda value=value: reject(lambda: s.FrozenJSONMap({'x': value})))
    for label, value in [('high_surrogate', '\ud800'), ('low_surrogate', '\udfff')]:
        for key in (True, False):
            data = {value: 1} if key else {'x': value}
            check(f'UNICODE-{label}-key{key}', 'local_shape',
                  lambda data=data: reject(lambda: s.FrozenJSONMap(data)))

    for candidate in ('A', 'C'):
        for realization in ('CI', 'OS', 'RG2b', 'PC', 'CI+PC'):
            name = f'{candidate}-{realization}'
            def shape(candidate=candidate, realization=realization):
                d = lifecycle_data(candidate, realization)
                value = s.GRCV4State(s.GRCV4LifecycleState(**d))
                equal(value.lifecycle.current.C, (1.0, 3.0))
                equal(value.lifecycle.reset.authoritative.C, (2.5, 1.5))
                require(value.lifecycle.current is not value.lifecycle.reset.authoritative)
                equal(value.budget_target, 4.0)
                require(value.remainder is None)
                equal([f.name for f in fields(value)], ['lifecycle'])
                if candidate == 'A':
                    equal(value.lifecycle.current.W_A, (0.75,))
                    equal(value.lifecycle.reset.authoritative.W_A, (1.25,))
                if realization in ('PC', 'CI+PC'):
                    equal(value.lifecycle.current.Z_4, (-0.5, 0.25))
                    equal(value.lifecycle.reset.authoritative.Z_4, (-1.0, 0.5))
                d['graph']['live_node_ids'].append('wrong')
                d['profile']['params_resolved']['reference'][0] = 99
                d['receipt_ledger'][0]['payload'][1]['flag'] = False
                equal(value.lifecycle.graph['live_node_ids'], ('a', 'b'))
                equal(value.lifecycle.profile['params_resolved']['reference'], (2.0, 4.0))
                require(value.lifecycle.receipt_ledger[0]['payload'][1]['flag'] is True)
            check('SHAPE-'+name, 'authority_shapes', shape)
            for location, channel in itertools.product(('current','reset'), ('W_A','Z_4')):
                def wrong_shape(candidate=candidate, realization=realization,
                                location=location, channel=channel):
                    d=lifecycle_data(candidate,realization)
                    old=d['current'] if location=='current' else d['reset'].authoritative
                    wrong=(1.0,) if getattr(old,channel) is None else None
                    new=replace(old,**{channel:wrong})
                    if location=='current': d[location]=new
                    else: d[location]=replace(d[location],authoritative=new)
                    return reject(lambda:s.GRCV4LifecycleState(**d))
                check(f'SHAPE-REJECT-{name}-{location}-{channel}', 'authority_shapes', wrong_shape)

    constructors={
        'list':lambda:[1.25,2.5], 'tuple':lambda:(1.25,2.5),
        'array':lambda:array('d',[1.25,2.5]),
        'memoryview-double':lambda:memoryview(array('d',[1.25,2.5]))}
    if np is not None:
        constructors.update({'numpy-contiguous':lambda:np.array([1.25,2.5]),
           'numpy-strided':lambda:np.array([1.25,99.,2.5,99.])[::2],
           'numpy-reversed':lambda:np.array([2.5,1.25])[::-1]})
    for channel, (kind, factory) in itertools.product(('C','W_A','Z_4'), constructors.items()):
        def array_detach(channel=channel, factory=factory):
            src=factory(); value=authority(channel,src)
            if not isinstance(src,tuple): src[0]=100.
            equal(getattr(value,channel),(1.25,2.5))
            require(type(getattr(value,channel)) is tuple)
            require(all(type(x) is float for x in getattr(value,channel)))
        check(f'ARRAY-DETACH-{channel}-{kind}', 'numeric_ownership', array_detach)

    for channel in ('C','W_A','Z_4'):
        for value in (math.nan, math.inf, -math.inf, -0.0, True, '1', object(),2**53,2**53+1):
            check(f'SCALAR-REJECT-{channel}-{repr(value)}','numeric_admission',
                  lambda channel=channel,value=value:reject(lambda:authority(channel,[value])))
        for value in (5e-324,sys.float_info.min,sys.float_info.max,2**53-1):
            check(f'SCALAR-ACCEPT-{channel}-{value}','numeric_admission',
                  lambda channel=channel,value=value:equal(getattr(authority(channel,[value]),channel),(float(value),)))
        check(f'ZERO-ARRAY-{channel}','numeric_admission',
              (lambda channel=channel:reject(lambda:authority(channel,[0.0]))) if channel=='W_A'
              else (lambda channel=channel:equal(getattr(authority(channel,[0.0]),channel),(0.0,))))

    # Required regression targets: unsafe integer adapters must not launder integers into floats.
    if np is not None:
        for channel in ('C','W_A','Z_4'):
            for value in (np.int64(2**53),np.int64(2**53+1),np.uint64(2**64-1)):
                check(f'UNSAFE-NUMPY-INTEGER-{channel}-{value}','unsafe_integer_adapter',
                      lambda channel=channel,value=value:reject(lambda:authority(channel,[value])))
        for value in (np.int64(-(2**53+1)), np.int64(-(2**63))):
            check(f'UNSAFE-NUMPY-INTEGER-Z_4-{value}', 'unsafe_integer_adapter',
                  lambda value=value: reject(lambda: authority('Z_4', [value])))
        for field in ('time','Q_target'):
            def bad_clock(field=field):
                d=lifecycle_data();d[field]=np.int64(2**53+1)
                if field=='Q_target':d['reset']=replace(d['reset'],Q_target=np.int64(2**53+1))
                return reject(lambda:s.GRCV4LifecycleState(**d))
            check('UNSAFE-NUMPY-INTEGER-'+field,'unsafe_integer_adapter',bad_clock)

    # Required local-shape regression targets: no byte/key/set reinterpretation as a vector.
    bad_vector_factories={
        'mapping':lambda:{1:-999.,2:math.nan}, 'set':lambda:{1.,2.},
        'frozenset':lambda:frozenset((1.,2.)), 'bytes':lambda:b'\x01\x02',
        'bytearray':lambda:bytearray((1,2)), 'empty-text':lambda:''}
    for channel,(kind,factory) in itertools.product(('C','W_A','Z_4'),bad_vector_factories.items()):
        check(f'BAD-VECTOR-CONTAINER-{channel}-{kind}','vector_container_admission',
              lambda channel=channel,factory=factory:reject(lambda:authority(channel,factory())))

    # Independent truth table for only the documented local result coherence, not receipt admission.
    solvers=[None,'valid_root','domain_failure','singular','conditioning_failure',
             'nonfinite','no_admitted_root','multiple_admitted_roots']
    for committed,operation,solver,has_failure,has_commit in itertools.product(
            (False,True),('committed','rejected'),solvers,(False,True),(False,True)):
        ok=((committed and operation=='committed' and solver=='valid_root'
             and not has_failure and has_commit)
            or (not committed and operation=='rejected' and has_failure and not has_commit))
        def result_matrix(committed=committed,operation=operation,solver=solver,
                          has_failure=has_failure,has_commit=has_commit,ok=ok):
            d=result_data();d.update(committed=committed,operation_disposition=operation,
                solver_disposition=solver,failure={'stage':'synthetic'} if has_failure else None,
                commit_id='synthetic-commit' if has_commit else None)
            if ok:
                result=s.GRCV4StepResult(**d)
                require(result.committed is committed)
                equal(result.solver_disposition,solver)
            else:return reject(lambda:s.GRCV4StepResult(**d))
        key=f'{committed}-{operation}-{solver}-{has_failure}-{has_commit}'
        check('STEP-RESULT-'+key,'result_truth_table',result_matrix)

    for committed,operation,has_failure,has_commit in itertools.product(
            (False,True),('committed','rejected'),(False,True),(False,True)):
        ok=((committed and operation=='committed' and not has_failure and has_commit)
            or (not committed and operation=='rejected' and has_failure and not has_commit))
        def life_result(committed=committed,operation=operation,
                        has_failure=has_failure,has_commit=has_commit,ok=ok):
            call=lambda:s.GRCV4LifecycleResult(operation,committed,
                'synthetic-commit' if has_commit else None,
                {'stage':'synthetic'} if has_failure else None,[])
            if ok: require(call().committed is committed)
            else:return reject(call)
        check(f'LIFECYCLE-RESULT-{committed}-{operation}-{has_failure}-{has_commit}',
              'result_truth_table',life_result)

    def events_and_observables():
        d=result_data(); value=s.GRCV4StepResult(**d)
        d['events'][0].payload['nested'][1]['flag']=False
        d['events'][0].kind='changed';d['events'].clear()
        d['observables']['x'][0]=99
        d['emitted_receipts'][0]['payload'].append(2)
        first,second=value.events,value.events
        require(first[0] is not second[0])
        require(first[0].payload is not second[0].payload)
        first[0].payload['nested'][1]['flag']=False
        first[0].kind='caller-changed'
        require(value.events[0].payload['nested'][1]['flag'] is True)
        equal(value.events[0].kind,'synthetic')
        equal(value.observables['x'],(0.25,))
        equal(value.emitted_receipts[0]['payload'],(1,))
        equal(copy(value),value);equal(deepcopy(value),value)
    check('EVENT-AND-OBSERVABLE-DETACH','common_projection',events_and_observables)

    # Advisory: Python mapping equality must not be mistaken for type-aware JSON identity.
    for left,right in [({'x':True},{'x':1}),({'x':False},{'x':0.0}),
                       ({'x':[{'flag':True}]},{'x':[{'flag':1}]})]:
        def json_type_distinction(left=left,right=right):
            a,b=s.FrozenJSONMap(left),s.FrozenJSONMap(right)
            require(typed_json(a.to_dict()) != typed_json(b.to_dict()))
            require(a != b,'Python equality collapses distinct JSON boolean/number values')
        check('JSON-EQUALITY-'+repr(left),'json_type_equality',json_type_distinction,'advisory')

    # Characterizations, not unsupported requirements for dataclass/pickle lifecycle APIs.
    characterizations={}
    for name,obj in [('map',s.FrozenJSONMap({'x':1})),('result',s.GRCV4StepResult(**result_data()))]:
        try:
            replace(obj)
            characterizations[name+'_dataclasses_replace']='works'
        except Exception as exc:
            characterizations[name+'_dataclasses_replace']=type(exc).__name__+': '+str(exc)
        characterizations[name+'_asdict_keys']=list(asdict(obj))
    proto=s.FrozenJSONMap({'x':1});proto.__init__({'x':2})
    characterizations['explicit_reinitialization_is_mutating']=proto.to_dict()=={'x':2}
    raw=s.GRCV4AuthoritativeState([1],None,None)
    raw.__setstate__([[9],None,None])
    characterizations['explicit_setstate_bypasses_freezing']=isinstance(raw.C,list)
    characterizations['hook_scope']='Deliberate special-method bypass, not a normal ownership-regression claim.'

    counts=Counter((row['tier'],row['pass']) for row in rows)
    groups={group:{'passed':sum(row['pass'] for row in rows if row['group']==group),
                   'total':sum(row['group']==group for row in rows)}
            for group in sorted({r['group'] for r in rows})}
    result={'audit_kind':'independent_P9-2.1_value_record_stress_not_runtime_conformance',
        'python':sys.version,'platform':platform.platform(),'numpy':None if np is None else np.__version__,
        'source_sha256':hashlib.sha256((root/'src/pygrc/models/grc_v4_state.py').read_bytes()).hexdigest(),
        'summary':{'total':len(rows),'required_passed':counts['required',True],
                   'required_failed':counts['required',False],
                   'advisory_passed':counts['advisory',True],
                   'advisory_failed':counts['advisory',False]},
        'groups':groups,'characterizations':characterizations,'cases':rows}
    args.output.write_text(json.dumps(result,indent=2,ensure_ascii=True)+'\n')
    print(json.dumps({'summary':result['summary'],'groups':groups},indent=2))
    return 1 if counts['required',False] else 0


if __name__=='__main__':
    raise SystemExit(main())

